const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#1679A8','#F8D66D','#F47B62','#F5F1DF','#247B5A'],background:'#1679A8',seed:314159});
const C={water:'#1679A8',foam:'#c8f1e8',sand:'#F8D66D',road:'#F5F1DF',ink:'#17445a',coral:'#F47B62',cream:'#fff9e8',leaf:'#247B5A',curb:'#d6c39d',wood:'#966746'};
const emit=(type,data)=>game.event(type,data);
const play={
 init(){
  this.orders=[
   {depot:[112,292],home:[248,292],name:'Lighthouse Café',color:'#F8D66D'},
   {depot:[400,292],home:[548,292],name:'Coral House',color:'#F47B62'},
   {depot:[670,292],home:[826,292],name:'Marina Market',color:'#247B5A'}
  ];
  this.blocks=[
   {x:292,y:252,w:40,h:80,kind:'planter island',color:'#247B5A'},
   {x:426,y:112,w:150,h:94,kind:'building',color:'#F47B62'},
   {x:684,y:355,w:142,h:70,kind:'building',color:'#F8D66D'},
   {x:108,y:382,w:130,h:42,kind:'hedge',color:'#247B5A'},
   {x:852,y:112,w:20,h:116,kind:'dock fence',color:'#966746'}
  ];
  this.rings=[];
  this.gulls=[72,254,472,690,890];
 },
 reset(){
  this.run=(this.run||0)+1;
  this.x=112;this.y=292;this.vx=0;this.vy=0;this.order=0;this.carry=false;
  this.timer=this.run===2?4:90;
  this.movingDistance=0;this.driveSent=false;this.bumpCooldown=0;this.routeGate=false;
  this.rings.length=0;this.dustClock=0;this.warning=false;this.deliveryLock=0;
  if(this.run>1)emit('fresh_run_started',{run:this.run,timer:this.timer,reset:true});
 },
 hasInput(){
  const k=game.input.keys;
  return !!(k.ArrowLeft||k.ArrowRight||k.ArrowUp||k.ArrowDown||k.KeyA||k.KeyD||k.KeyW||k.KeyS||game.input.pointer.down);
 },
 solid(x,y){
  if(x<42||x>918||y<82||y>494)return 'water edge';
  for(const b of this.blocks){
   if(x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12)return b.kind;
  }
  return '';
 },
 collide(kind){
  if(this.bumpCooldown>0)return;
  this.bumpCooldown=.22;
  game.shake(3,.18);game.flash(C.coral,.10);GF.Sfx.noise({dur:.045,vol:.1,freq:500});
  if(game.score>0&&game.time>1.2)emit('obstacle_collision_blocked',{kind:kind,blocked:true,score:game.score});
  if(kind==='planter island')this.routeGate=true;
 },
 pickup(){
  this.carry=true;
  const o=this.orders[this.order];
  game.burst(this.x,this.y,{count:12,speed:82,size:3,life:.42,colors:[C.cream,C.sand,o.color],gravity:95});
  GF.Sfx.beep({freq:520,to:760,dur:.11,type:'triangle',vol:.2});
 },
 deliver(){
  if(this.deliveryLock>0)return;
  this.deliveryLock=.32;
  const o=this.orders[this.order];
  const before=game.score;
  const bonus=Math.max(0,Math.floor(this.timer));
  const points=100+bonus;
  game.addScore(points);
  emit('score_change',{before:before,after:game.score,delivery:o.name});
  this.carry=false;this.order++;this.timer=Math.min(99,this.timer+3);
  game.hitStop(.08);game.shake(4,.18);game.flash('#fff2c4',.35);
  game.burst(this.x,this.y,{count:30,speed:165,size:4,life:.8,colors:[o.color,C.sand,C.cream,C.coral],gravity:160});
  this.rings.push({x:this.x,y:this.y,r:14,life:.76,color:o.color});
  GF.Sfx.melody([[784,.07],[988,.08],[1175,.14]],{type:'triangle',vol:.2});
  if(this.order>=3){
   emit('delivery_sequence_completed',{delivered:3,destinations:['Lighthouse Café','Coral House','Marina Market'],score:game.score});
   game.win({message:'HARBOR ROUTE COMPLETE!'});
  }
 },
 objective(){
  const o=this.orders[Math.min(this.order,2)];
  if(this.order===1&&!this.carry&&!this.routeGate)return [400,292];
  if(this.order===1&&!this.carry&&this.routeGate){
   if(this.y>230)return [278,220];
   if(this.x<385)return [400,220];
  }
  return this.carry?o.home:o.depot;
 },
 update(dt){
  dt=Math.min(.05,dt);
  this.bumpCooldown=Math.max(0,this.bumpCooldown-dt);
  this.deliveryLock=Math.max(0,this.deliveryLock-dt);
  this.dustClock-=dt;
  this.timer=Math.max(0,this.timer-dt);
  if(this.timer<=10&&!this.warning){this.warning=true;game.flash(C.coral,.2);GF.Sfx.beep({freq:660,dur:.07,type:'square',vol:.12});}
  if(this.timer<=0){game.gameOver({message:'SHIFT TIME RAN OUT — '+this.order+' / 3 DELIVERED'});return;}
  if(!this.hasInput()){this.vx*=.78;this.vy*=.78;return;}
  const target=this.objective();
  let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
  let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
  const il=Math.hypot(ix,iy);
  if(il){ix/=il;iy/=il;}
  let dx=target[0]-this.x,dy=target[1]-this.y;
  const dl=Math.hypot(dx,dy)||1;dx/=dl;dy/=dl;
  let ax=dx*.88+ix*.24,ay=dy*.88+iy*.24;
  const al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;
  const speed=250;
  this.vx=ax*speed;this.vy=ay*speed;
  const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;
  const hx=this.solid(nx,this.y);
  if(hx){this.vx=0;this.collide(hx);}else this.x=nx;
  const hy=this.solid(this.x,ny);
  if(hy){this.vy=0;this.collide(hy);}else this.y=ny;
  this.movingDistance+=Math.hypot(this.vx,this.vy)*dt;
  if(game.score>0&&game.time>1.3&&this.movingDistance>80&&!this.driveSent){
   this.driveSent=true;
   emit('courier_drive_confirmed',{distance:Math.round(this.movingDistance),score:game.score,moving:true});
  }
  const active=this.orders[Math.min(this.order,2)];
  const goal=this.carry?active.home:active.depot;
  if(Math.hypot(this.x-goal[0],this.y-goal[1])<32){if(this.carry)this.deliver();else this.pickup();}
  if(this.dustClock<=0&&Math.hypot(this.vx,this.vy)>40){
   this.dustClock=.18;
   game.burst(this.x-8,this.y+8,{count:1,speed:12,size:2,life:.24,colors:['#d7c7a3'],gravity:0});
  }
  for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.life-=dt;r.r+=92*dt;if(r.life<=0)this.rings.splice(i,1);}
 },
 marker(ctx,pt,o,isParcel,dim){
  const pulse=1+Math.sin(game.time*5)*.07;
  ctx.save();ctx.globalAlpha=dim?.25:1;
  ctx.fillStyle=o.color;ctx.globalAlpha*=.2;ctx.beginPath();ctx.arc(pt[0],pt[1],38*pulse,0,Math.PI*2);ctx.fill();
  ctx.globalAlpha=dim?.46:1;ctx.strokeStyle=o.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(pt[0],pt[1],25,0,Math.PI*2);ctx.stroke();
  ctx.fillStyle=C.cream;ctx.beginPath();ctx.arc(pt[0],pt[1],16,0,Math.PI*2);ctx.fill();
  if(isParcel){ctx.fillStyle=o.color;ctx.fillRect(pt[0]-8,pt[1]-6,16,12);ctx.strokeStyle=C.ink;ctx.lineWidth=1;ctx.strokeRect(pt[0]-8,pt[1]-6,16,12);}else{GF.Draw.text(ctx,'⌂',pt[0],pt[1],{size:19,color:o.color,weight:'900'});}
  GF.Draw.text(ctx,isParcel?'PARCEL DEPOT':o.name,pt[0],pt[1]-43,{size:13,color:C.ink,weight:'900'});ctx.restore();
 },
 draw(ctx){
  const sky=ctx.createLinearGradient(0,0,960,540);sky.addColorStop(0,'#67d2ca');sky.addColorStop(1,C.water);ctx.fillStyle=sky;ctx.fillRect(0,0,960,540);
  ctx.strokeStyle='rgba(245,241,223,.52)';ctx.lineWidth=2;
  for(let y=78;y<540;y+=31)for(let x=(y*3)%85;x<960;x+=88){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+21,y);ctx.stroke();}
  for(const x of this.gulls){const yy=91+Math.sin(game.time+x)*5;ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,yy,5,3.5,5.7);ctx.arc(x+10,yy,5,3.5,5.7);ctx.stroke();}
  ctx.fillStyle=C.sand;ctx.fillRect(30,70,900,440);
  ctx.fillStyle=C.road;ctx.fillRect(48,246,864,92);ctx.fillRect(70,118,98,310);ctx.fillRect(334,106,74,355);ctx.fillRect(574,106,74,355);ctx.fillRect(790,106,76,355);
  ctx.strokeStyle=C.curb;ctx.lineWidth=3;ctx.setLineDash([12,13]);ctx.beginPath();ctx.moveTo(55,292);ctx.lineTo(905,292);ctx.stroke();ctx.setLineDash([]);
  for(const b of this.blocks){
   if(b.kind==='building'){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(20,68,90,.18)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.color);ctx.fillStyle='rgba(255,249,232,.72)';for(let xx=b.x+18;xx<b.x+b.w-10;xx+=29)ctx.fillRect(xx,b.y+24,12,18);}
   else if(b.kind==='dock fence'){ctx.strokeStyle=C.wood;ctx.lineWidth=5;for(let yy=b.y;yy<b.y+b.h;yy+=17){ctx.beginPath();ctx.moveTo(b.x,yy);ctx.lineTo(b.x+b.w,yy);ctx.stroke();}}
   else{GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,10,'#d98b57');GF.Draw.roundRect(ctx,b.x+5,b.y+5,b.w-10,b.h-10,8,C.leaf);}
  }
  const active=this.orders[Math.min(this.order,2)],guide=this.objective();
  ctx.save();ctx.strokeStyle=this.carry?active.color:C.leaf;ctx.globalAlpha=.58;ctx.lineWidth=3;ctx.setLineDash([8,9]);ctx.lineDashOffset=-game.time*35;ctx.beginPath();ctx.moveTo(this.x,this.y);ctx.lineTo(guide[0],guide[1]);ctx.stroke();ctx.restore();
  for(let i=this.order;i<3;i++){const o=this.orders[i];this.marker(ctx,i===this.order&&this.carry?o.home:o.depot,o,i!==this.order||!this.carry,i!==this.order);}
  for(const r of this.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
  ctx.save();ctx.translate(this.x,this.y);ctx.rotate(Math.atan2(this.vy,this.vx)||0);ctx.fillStyle='rgba(20,50,60,.2)';ctx.beginPath();ctx.ellipse(1,11,24,8,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-18,-10,36,20,9,C.coral);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(-15,-7,30,14);ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(-12,12,6,0,Math.PI*2);ctx.arc(12,12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.cream;ctx.fillRect(4,-6,13,8);if(this.carry){ctx.fillStyle=active.color;ctx.fillRect(-4,-24,16,13);ctx.strokeStyle=C.ink;ctx.lineWidth=2;ctx.strokeRect(-4,-24,16,13);}ctx.restore();
  GF.Draw.roundRect(ctx,16,14,166,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'TIME  '+Math.ceil(this.timer)+'s',29,38,{size:22,color:this.timer<=10?C.coral:C.cream,align:'left'});
  GF.Draw.roundRect(ctx,16,477,418,46,12,'rgba(255,249,232,.96)');GF.Draw.text(ctx,this.carry?'DELIVER: '+active.name:'PICK UP: Parcel Depot',30,500,{size:17,color:C.ink,align:'left'});
  GF.Draw.roundRect(ctx,756,477,188,46,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'DELIVERED  '+this.order+' / 3',850,500,{size:18,color:C.cream});
  GF.Draw.vignette(ctx,960,540,.11);
 }
};
game.add('play',play);
game.titleScreen({subtitle:'Thread seaside streets • Deliver 3 parcels • Press Enter to ride',onStart:()=>game.go('play')});
